import itertools, random
from fractions import Fraction

def rank(A):
 A=[list(r) for r in A]; nr=len(A); nc=len(A[0]); r=0
 for c in range(nc):
  p=next((i for i in range(r,nr) if A[i][c]),None)
  if p is None: continue
  A[r],A[p]=A[p],A[r]; q=A[r][c]
  for j in range(c,nc): A[r][j]/=q
  for i in range(r+1,nr):
   q=A[i][c]
   if q:
    for j in range(c,nc): A[i][j]-=q*A[r][j]
  r+=1
  if r==nr: break
 return r
for n in [5,6]:
 H=(2**n-1+n-1)//n
