const r = await tools.exec_command({cmd:"python3 - <<'PY'
import itertools, numpy as np
from fractions import Fraction

def null_hyper(B,n):
 # solve augmented row [1,x] null vector exactly, require rank n
 A=[[Fraction(1)]+[Fraction(v) for v in x] for x in B]
 # rref, null dim should1
 M=[r[:] for r in A]; rows=len(M); cols=n+1; piv=[]; rr=0
 for c in range(cols):
  p=next((i for i in range(rr,rows) if M[i][c]),None)
  if p is None: continue
  M[rr],M[p]=M[p],M[rr]; q=M[rr][c]; M[rr]=[z/q for z in M[rr]]
  for i in range(rows):
   if i!=rr and M[i][c]:
    q=M[i][c]; M[i]=[a-q*b for a,b in zip(M[i],M[rr])]
  piv.append(c); rr+=1
  if rr==rows:break
 if rr<n:return None
 free=next(c for c in range(cols) if c not in piv); z=[Fraction(0)]*cols; z[free]=1
 for i,c in reversed(list(enumerate(piv))): z[c]=-sum(M[i][j]*z[j] for j in range(c+1,cols))
 return z
for n in range(3,9):
 X=list(itertools.product([0,1],repeat=n))
 # integer binary order with product lex (000,001,...)
 blocks=[X[i:i+n] for i in range(1,len(X),n)]
 print('n',n,'blocks',len(blocks))
 bad=0
 for bi,B in enumerate(blocks):
  if len(B)<n:continue
  z=null_hyper(B,n)
  if z is None: count=-1
  else: count=sum(sum(a*b for a,b in zip(z,[1]+list(x)))==0 for x in X)
  if count!=n:
   bad+=1
   if bad<4: print(' bad',bi,'count',count,'B',B)
 print(' bad total',bad)
