#!/usr/bin/env python3
from math import ceil
from random import Random

import numpy as np


P = 1_000_000_007


def rank_mod(matrix):
    matrix = np.asarray(matrix, dtype=np.int64)
    rank = 0
    for column in range(matrix.shape[1]):
        candidates = np.flatnonzero(matrix[rank:, column])
        if not len(candidates):
            continue
        pivot = rank + int(candidates[0])
        if pivot != rank:
            matrix[[rank, pivot]] = matrix[[pivot, rank]]
        inv = pow(int(matrix[rank, column]), P - 2, P)
        matrix[rank, column:] = matrix[rank, column:] * inv % P
        targets = np.flatnonzero(matrix[rank + 1 :, column]) + rank + 1
        for start in range(0, len(targets), 64):
            batch = targets[start:start + 64]
            scales = matrix[batch, column].copy()
            matrix[batch, column:] = (
                matrix[batch, column:]
                - scales[:, None] * matrix[rank, column:]
            ) % P
        rank += 1
        if rank == matrix.shape[0]:
            break
    return rank


def confluent(n, seed):
    random = Random(seed)
    weights = [random.randrange(1, 1000) for _ in range(n)]
    count = (1 << n) - 1
    width = ceil(count / n)
    rows = []
    for word in range(1, 1 << n):
        z = sum(weights[i] for i in range(n) if word >> i & 1) % P
        powers = [1]
        for _ in range(1, width):
            powers.append(powers[-1] * z % P)
        rows.append([
            (powers[k] if word >> i & 1 else 0)
            for k in range(width)
            for i in range(n)
        ])
    return width, rank_mod(rows)


for dimension in range(2, 12):
    width, rank = confluent(dimension, 17000 + dimension)
    print(dimension, width, rank, (1 << dimension) - 1)

