#!/usr/bin/env python3
from fractions import Fraction as F
from itertools import product


R = 3
M = 1 << R
H = M - 1
N = R + M
ADDRESSES = list(product([0, 1], repeat=R))
NODES = [sum((1 << i) * bit for i, bit in enumerate(a)) for a in ADDRESSES]


def solve_linear(rows, rhs, variable_count):
    matrix = [
        [F(value) for value in row] + [F(value_rhs)]
        for row, value_rhs in zip(rows, rhs)
    ]
    rank = 0
    pivots = []
    for column in range(variable_count):
        pivot = next((i for i in range(rank, len(matrix)) if matrix[i][column]), None)
        if pivot is None:
            continue
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]
        scale = matrix[rank][column]
        matrix[rank] = [value / scale for value in matrix[rank]]
        for i in range(len(matrix)):
            if i != rank and matrix[i][column]:
                scale = matrix[i][column]
                matrix[i] = [
                    left - scale * right
                    for left, right in zip(matrix[i], matrix[rank])
                ]
        pivots.append(column)
        rank += 1
    assert all(any(row[:-1]) or not row[-1] for row in matrix)
    answer = [F(0)] * variable_count
    for row, pivot in zip(matrix[:rank], pivots):
        answer[pivot] = row[-1]
    return answer


reciprocal = [
    [F(1, node + h + 1) for h in range(H)]
    for node in NODES
]
normal = []
for a, node in enumerate(NODES):
    q_value = 1
    for h in range(H):
        q_value *= node + h + 1
    v_derivative = 1
    for b, other in enumerate(NODES):
        if b != a:
            v_derivative *= node - other
    normal.append(F(q_value, v_derivative))
normal_scale = max(abs(value) for value in normal)
normal = [value / normal_scale for value in normal]

# Solve simultaneously for address-affine U_h such that
# sum_h U_h(a)/A_h(a)=0 and delta_h=sum_a c_a U_h(a)/A_h(a)^2
# equals (-1,+1,0,...).  Then gamma_h=c^T(-U_h/A_h^2)=(+1,-1,0,...).
variable_count = H * (R + 1)
cancel_rows = []
for a, address in enumerate(ADDRESSES):
    row = []
    for h in range(H):
        row.extend(
            [reciprocal[a][h]]
            + [bit * reciprocal[a][h] for bit in address]
        )
    cancel_rows.append(row)

delta_rows = [[F(0)] * variable_count for _ in range(H)]
for h in range(H):
    for j in range(R + 1):
        delta_rows[h][h * (R + 1) + j] = sum(
            normal[a]
            * (1 if j == 0 else ADDRESSES[a][j - 1])
            * reciprocal[a][h] ** 2
            for a in range(M)
        )

u_flat = solve_linear(
    cancel_rows + delta_rows,
    [F(0)] * M + [F(-1), F(1)] + [F(0)] * (H - 2),
    variable_count,
)
u = [u_flat[h * (R + 1):(h + 1) * (R + 1)] for h in range(H)]

u_values = [
    [u[h][0] + sum(u[h][i + 1] * address[i] for i in range(R)) for h in range(H)]
    for address in ADDRESSES
]
assert all(
    sum(u_values[a][h] * reciprocal[a][h] for h in range(H)) == 0
    for a in range(M)
)
g = [
    [-u_values[a][h] * reciprocal[a][h] ** 2 for h in range(H)]
    for a in range(M)
]
gamma = [sum(normal[a] * g[a][h] for a in range(M)) for h in range(H)]
assert gamma == [F(1), F(-1)] + [F(0)] * (H - 2)

# Positive data coefficients q_hb with gamma dot q_b = c_b.
offset = F(2)
q = [[offset for _ in range(M)] for _ in range(H)]
for b in range(M):
    if normal[b] >= 0:
        q[0][b] += normal[b]
    else:
        q[1][b] += -normal[b]
    assert all(q[h][b] > 0 for h in range(H))
    assert sum(gamma[h] * q[h][b] for h in range(H)) == normal[b]

# Solve R v_b = e_b - G q_b.  The right side is normal-orthogonal,
# so it lies in the H-dimensional Cauchy column space.
v = [[F(0) for _ in range(M)] for _ in range(H)]
for b in range(M):
    right = [
        F(int(a == b)) - sum(g[a][h] * q[h][b] for h in range(H))
        for a in range(M)
    ]
    assert sum(normal[a] * right[a] for a in range(M)) == 0
    solution = solve_linear(reciprocal, right, H)
    for h in range(H):
        v[h][b] = solution[h]
    assert all(
        sum(reciprocal[a][h] * solution[h] for h in range(H)) == right[a]
        for a in range(M)
    )

# Verify the limiting coefficient matrix is exactly the identity.
for a in range(M):
    for b in range(M):
        coefficient = sum(
            reciprocal[a][h] * v[h][b] + g[a][h] * q[h][b]
            for h in range(H)
        )
        assert coefficient == int(a == b)


def certificate(epsilon):
    denominators = []
    numerators = []
    for h in range(H):
        # A_h(a)=h+1 + sum_i 2^i a_i.
        denominator = [F(h + 1)] + [F(1 << i) for i in range(R)] + [
            epsilon * q[h][b] for b in range(M)
        ]
        numerator = [u[h][0] / epsilon] + [
            u[h][i + 1] / epsilon for i in range(R)
        ] + [v[h][b] for b in range(M)]
        denominators.append(denominator)
        numerators.append(numerator)

    # Subtract 1/2 from the complete score exactly.
    numerators[0] = [
        left - F(1, 2) * right
        for left, right in zip(numerators[0], denominators[0])
    ]
    return denominators, numerators


def margin(denominators, numerators):
    minimum = None
    for x in product([0, 1], repeat=N):
        address = sum((1 << i) * x[i] for i in range(R))
        label = 1 if x[R + address] else -1
        score = F(0)
        for denominator, numerator in zip(denominators, numerators):
            d = denominator[0] + sum(c * bit for c, bit in zip(denominator[1:], x))
            value = numerator[0] + sum(c * bit for c, bit in zip(numerator[1:], x))
            assert d > 0
            score += value / d
        signed = label * score
        minimum = signed if minimum is None else min(minimum, signed)
    return minimum


for exponent in range(1, 9):
    epsilon = F(1, 10**exponent)
    denominators, numerators = certificate(epsilon)
    minimum = margin(denominators, numerators)
    print("epsilon", epsilon, "margin", minimum, float(minimum))
    if minimum > 0:
        print("FOUND")
        print("DENOMINATORS", repr(denominators))
        print("NUMERATORS", repr(numerators))
        break

