#!/usr/bin/env python3
"""Exact seven-head certificate for the three-bit address function."""

from fractions import Fraction as F
from itertools import product


ADDRESS_BITS = 3
DATA_COUNT = 1 << ADDRESS_BITS
HEAD_COUNT = DATA_COUNT - 1
VARIABLE_COUNT = ADDRESS_BITS + DATA_COUNT
ADDRESSES = list(product([0, 1], repeat=ADDRESS_BITS))
NODES = [
    sum((1 << i) * bit for i, bit in enumerate(address))
    for address in ADDRESSES
]
ROW_FOR_NODE = {node: row for row, node in enumerate(NODES)}


def solve_linear(rows, right_hand_side, column_count):
    """Return one exact solution, setting all free variables to zero."""
    matrix = [
        [F(value) for value in row] + [F(right)]
        for row, right in zip(rows, right_hand_side)
    ]
    rank = 0
    pivots = []
    for column in range(column_count):
        pivot = next(
            (i for i in range(rank, len(matrix)) if matrix[i][column]),
            None,
        )
        if pivot is None:
            continue
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]
        scale = matrix[rank][column]
        matrix[rank] = [value / scale for value in matrix[rank]]
        for i in range(len(matrix)):
            if i != rank and matrix[i][column]:
                scale = matrix[i][column]
                matrix[i] = [
                    left - scale * right
                    for left, right in zip(matrix[i], matrix[rank])
                ]
        pivots.append(column)
        rank += 1
    assert all(any(row[:-1]) or not row[-1] for row in matrix)
    answer = [F(0)] * column_count
    for row, pivot in zip(matrix[:rank], pivots):
        answer[pivot] = row[-1]
    return answer


def construct_certificate():
    # Address-only Cauchy denominators A_h(a)=z(a)+h+1.
    reciprocal = [
        [F(1, node + h + 1) for h in range(HEAD_COUNT)]
        for node in NODES
    ]

    # A left-null vector of the rectangular Cauchy matrix.
    normal = []
    for a, node in enumerate(NODES):
        q_value = 1
        for h in range(HEAD_COUNT):
            q_value *= node + h + 1
        vandermonde_derivative = 1
        for b, other in enumerate(NODES):
            if b != a:
                vandermonde_derivative *= node - other
        normal.append(F(q_value, vandermonde_derivative))
    scale = max(abs(value) for value in normal)
    normal = [value / scale for value in normal]
    assert all(
        sum(normal[a] * reciprocal[a][h] for a in range(DATA_COUNT)) == 0
        for h in range(HEAD_COUNT)
    )

    # Find address-affine U_h with exact leading cancellation and quotient
    # coordinates gamma=(1,-1,0,...).  These are finite rational equations.
    u_column_count = HEAD_COUNT * (ADDRESS_BITS + 1)
    cancellation_rows = []
    for a, address in enumerate(ADDRESSES):
        row = []
        for h in range(HEAD_COUNT):
            row.extend(
                [reciprocal[a][h]]
                + [bit * reciprocal[a][h] for bit in address]
            )
        cancellation_rows.append(row)

    quotient_rows = [[F(0)] * u_column_count for _ in range(HEAD_COUNT)]
    for h in range(HEAD_COUNT):
        for j in range(ADDRESS_BITS + 1):
            quotient_rows[h][h * (ADDRESS_BITS + 1) + j] = sum(
                normal[a]
                * (1 if j == 0 else ADDRESSES[a][j - 1])
                * reciprocal[a][h] ** 2
                for a in range(DATA_COUNT)
            )

    u_flat = solve_linear(
        cancellation_rows + quotient_rows,
        [F(0)] * DATA_COUNT
        + [F(-1), F(1)]
        + [F(0)] * (HEAD_COUNT - 2),
        u_column_count,
    )
    u = [
        u_flat[h * (ADDRESS_BITS + 1):(h + 1) * (ADDRESS_BITS + 1)]
        for h in range(HEAD_COUNT)
    ]
    u_values = [
        [
            u[h][0]
            + sum(u[h][i + 1] * address[i] for i in range(ADDRESS_BITS))
            for h in range(HEAD_COUNT)
        ]
        for address in ADDRESSES
    ]
    assert all(
        sum(
            u_values[a][h] * reciprocal[a][h]
            for h in range(HEAD_COUNT)
        ) == 0
        for a in range(DATA_COUNT)
    )

    first_order = [
        [
            -u_values[a][h] * reciprocal[a][h] ** 2
            for h in range(HEAD_COUNT)
        ]
        for a in range(DATA_COUNT)
    ]
    gamma = [
        sum(normal[a] * first_order[a][h] for a in range(DATA_COUNT))
        for h in range(HEAD_COUNT)
    ]
    assert gamma == [F(1), F(-1)] + [F(0)] * (HEAD_COUNT - 2)

    # Choose every data coefficient of every denominator strictly positive.
    # The two opposite quotient directions still let their weighted difference
    # match either sign of the required Cauchy normal coordinate.
    offset = F(2)
    data_denominator = [
        [offset for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    for b in range(DATA_COUNT):
        target_normal = normal[ROW_FOR_NODE[b]]
        if target_normal >= 0:
            data_denominator[0][b] += target_normal
        else:
            data_denominator[1][b] += -target_normal
        assert sum(
            gamma[h] * data_denominator[h][b]
            for h in range(HEAD_COUNT)
        ) == target_normal

    # The residual of each selector column is normal-orthogonal and hence has
    # a unique expansion in the seven Cauchy columns.
    data_numerator = [
        [F(0) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    for b in range(DATA_COUNT):
        residual = [
            F(int(NODES[a] == b))
            - sum(
                first_order[a][h] * data_denominator[h][b]
                for h in range(HEAD_COUNT)
            )
            for a in range(DATA_COUNT)
        ]
        assert sum(
            normal[a] * residual[a] for a in range(DATA_COUNT)
        ) == 0
        solution = solve_linear(reciprocal, residual, HEAD_COUNT)
        for h in range(HEAD_COUNT):
            data_numerator[h][b] = solution[h]
        assert all(
            sum(
                reciprocal[a][h] * solution[h]
                for h in range(HEAD_COUNT)
            ) == residual[a]
            for a in range(DATA_COUNT)
        )

    epsilon = F(1, 1_000_000_000)
    denominators = []
    numerators = []
    for h in range(HEAD_COUNT):
        denominators.append(
            [F(h + 1)]
            + [F(1 << i) for i in range(ADDRESS_BITS)]
            + [epsilon * data_denominator[h][b] for b in range(DATA_COUNT)]
        )
        numerators.append(
            [u[h][0] / epsilon]
            + [u[h][i + 1] / epsilon for i in range(ADDRESS_BITS)]
            + [data_numerator[h][b] for b in range(DATA_COUNT)]
        )

    # The desired limiting score is y_a; subtract 1/2 exactly.
    numerators[0] = [
        left - F(1, 2) * right
        for left, right in zip(numerators[0], denominators[0])
    ]
    return denominators, numerators


def main():
    denominators, numerators = construct_certificate()
    minimum_margin = None
    for x in product([0, 1], repeat=VARIABLE_COUNT):
        address = sum((1 << i) * x[i] for i in range(ADDRESS_BITS))
        label = 1 if x[ADDRESS_BITS + address] else -1
        score = F(0)
        for denominator, numerator in zip(denominators, numerators):
            denominator_value = denominator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(denominator[1:], x)
            )
            numerator_value = numerator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(numerator[1:], x)
            )
            assert denominator_value > 0
            assert all(coefficient > 0 for coefficient in denominator[1:])
            score += numerator_value / denominator_value
        signed_margin = label * score
        minimum_margin = (
            signed_margin
            if minimum_margin is None
            else min(minimum_margin, signed_margin)
        )
    assert minimum_margin > F(467, 1000)
    print("IDX_3 seven-head rational certificate: exact")
    print(f"minimum signed margin: {minimum_margin}")


if __name__ == "__main__":
    main()

