from itertools import product

import numpy as np


for r in range(2, 9):
    m = 1 << r
    h_count = m - 1
    addresses = list(product([0, 1], repeat=r))
    nodes = np.array([sum((1 << i) * bit for i, bit in enumerate(a)) for a in addresses])
    reciprocal = np.array([[1.0 / (z + h + 1) for h in range(h_count)] for z in nodes])
    _, _, vt = np.linalg.svd(reciprocal.T)
    c = vt[-1]
    found = None
    for bit in range(r):
        zeros = [a for a, address in enumerate(addresses) if address[bit] == 0]
        for p_index, p in enumerate(zeros):
            for q in zeros[p_index + 1:]:
                b = np.zeros(m)
                b[p] = c[q]
                b[q] = -c[p]
                beta, *_ = np.linalg.lstsq(reciprocal, b, rcond=None)
                if np.max(np.abs(reciprocal @ beta - b)) > 1e-5:
                    continue
                delta = np.array([
                    sum(c[a] * addresses[a][bit] / (nodes[a] + h + 1) ** 2 for a in range(m))
                    for h in range(h_count)
                ])
                gamma = -beta * delta
                if np.min(gamma) < -1e-9 and np.max(gamma) > 1e-9:
                    found = (bit, nodes[p], nodes[q], np.min(gamma), np.max(gamma))
                    break
            if found:
                break
        if found:
            break
    print(r, found)

