#!/usr/bin/env python3
"""Exact five-head certificate for the three-bit address function."""

from fractions import Fraction as F
from itertools import product


ADDRESS_BITS = 3
DATA_COUNT = 1 << ADDRESS_BITS
HEAD_COUNT = 5
VARIABLE_COUNT = ADDRESS_BITS + DATA_COUNT
ADDRESSES = list(product([0, 1], repeat=ADDRESS_BITS))
NODES = [
    sum((1 << i) * bit for i, bit in enumerate(address))
    for address in ADDRESSES
]
ROW_FOR_NODE = {node: row for row, node in enumerate(NODES)}


def rref(rows, column_count):
    matrix = [[F(value) for value in row] for row in rows]
    rank = 0
    pivots = []
    for column in range(column_count):
        pivot = next(
            (i for i in range(rank, len(matrix)) if matrix[i][column]),
            None,
        )
        if pivot is None:
            continue
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]
        scale = matrix[rank][column]
        matrix[rank] = [value / scale for value in matrix[rank]]
        for i in range(len(matrix)):
            if i != rank and matrix[i][column]:
                scale = matrix[i][column]
                matrix[i] = [
                    left - scale * right
                    for left, right in zip(matrix[i], matrix[rank])
                ]
        pivots.append(column)
        rank += 1
    return matrix, pivots


def nullspace(rows, column_count):
    matrix, pivots = rref(rows, column_count)
    basis = []
    for free in (j for j in range(column_count) if j not in pivots):
        vector = [F(0)] * column_count
        vector[free] = F(1)
        for row, pivot in zip(matrix[: len(pivots)], pivots):
            vector[pivot] = -row[free]
        basis.append(vector)
    return basis


def solve_linear(rows, right_hand_side, column_count):
    augmented = [
        list(row) + [right]
        for row, right in zip(rows, right_hand_side)
    ]
    matrix, pivots = rref(augmented, column_count)
    assert all(
        any(row[:column_count]) or not row[-1]
        for row in matrix
    )
    answer = [F(0)] * column_count
    for row, pivot in zip(matrix[: len(pivots)], pivots):
        answer[pivot] = row[-1]
    return answer


def positive_null_vector(rows):
    basis = nullspace(rows, HEAD_COUNT)
    assert len(basis) == 2
    first, second = basis
    candidates = [
        (first, second),
        ([-value for value in first], second),
        (second, first),
        ([-value for value in second], first),
    ]
    for base, direction in candidates:
        lower = None
        upper = None
        feasible = True
        for left, slope in zip(base, direction):
            if slope > 0:
                bound = -left / slope
                lower = bound if lower is None else max(lower, bound)
            elif slope < 0:
                bound = -left / slope
                upper = bound if upper is None else min(upper, bound)
            elif left <= 0:
                feasible = False
        if not feasible or (
            lower is not None and upper is not None and lower >= upper
        ):
            continue
        if lower is None:
            parameter = upper - 1
        elif upper is None:
            parameter = lower + 1
        else:
            parameter = (lower + upper) / 2
        result = [
            left + parameter * slope
            for left, slope in zip(base, direction)
        ]
        if all(value > 0 for value in result):
            return result
    raise AssertionError("quotient columns do not positively span")


def construct_certificate():
    reciprocal = [
        [F(1, node + h + 1) for h in range(HEAD_COUNT)]
        for node in NODES
    ]
    normal_columns = nullspace(
        list(zip(*reciprocal)),
        DATA_COUNT,
    )
    assert len(normal_columns) == DATA_COUNT - HEAD_COUNT
    normal_rows = [
        [
            normal_columns[j][a]
            for j in range(DATA_COUNT - HEAD_COUNT)
        ]
        for a in range(DATA_COUNT)
    ]

    cancellation_rows = []
    for a, address in enumerate(ADDRESSES):
        row = []
        for h in range(HEAD_COUNT):
            row.extend(
                [reciprocal[a][h]]
                + [bit * reciprocal[a][h] for bit in address]
            )
        cancellation_rows.append(row)
    cancellation_basis = nullspace(
        cancellation_rows,
        HEAD_COUNT * (ADDRESS_BITS + 1),
    )
    assert len(cancellation_basis) == 12

    # A fixed rational cancellation relation; the coefficients merely select
    # one vector in the exact nullspace above.
    combination = [4, -4, -1, 3, 1, -3, 3, 1, -3, 3, 2, -3]
    u_flat = [
        sum(
            coefficient * basis[j]
            for coefficient, basis in zip(combination, cancellation_basis)
        )
        for j in range(HEAD_COUNT * (ADDRESS_BITS + 1))
    ]
    u = [
        u_flat[h * (ADDRESS_BITS + 1):(h + 1) * (ADDRESS_BITS + 1)]
        for h in range(HEAD_COUNT)
    ]
    u_values = [
        [
            u[h][0]
            + sum(
                u[h][i + 1] * address[i]
                for i in range(ADDRESS_BITS)
            )
            for h in range(HEAD_COUNT)
        ]
        for address in ADDRESSES
    ]
    assert all(
        sum(
            u_values[a][h] * reciprocal[a][h]
            for h in range(HEAD_COUNT)
        ) == 0
        for a in range(DATA_COUNT)
    )

    first_order = [
        [
            -u_values[a][h] * reciprocal[a][h] ** 2
            for h in range(HEAD_COUNT)
        ]
        for a in range(DATA_COUNT)
    ]
    quotient = [
        [
            sum(
                normal_rows[a][j] * first_order[a][h]
                for a in range(DATA_COUNT)
            )
            for h in range(HEAD_COUNT)
        ]
        for j in range(DATA_COUNT - HEAD_COUNT)
    ]
    positive_kernel = positive_null_vector(quotient)

    data_denominator = [
        [F(0) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    data_numerator = [
        [F(0) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    for b in range(DATA_COUNT):
        target = normal_rows[ROW_FOR_NODE[b]]
        particular = solve_linear(quotient, target, HEAD_COUNT)
        multiplier = F(0)
        for value, direction in zip(particular, positive_kernel):
            if value <= 0:
                multiplier = max(
                    multiplier,
                    -value / direction + 1,
                )
        data_coefficients = [
            value + multiplier * direction
            for value, direction in zip(particular, positive_kernel)
        ]
        assert all(value > 0 for value in data_coefficients)
        for h in range(HEAD_COUNT):
            data_denominator[h][b] = data_coefficients[h]

        residual = [
            F(int(NODES[a] == b))
            - sum(
                first_order[a][h] * data_denominator[h][b]
                for h in range(HEAD_COUNT)
            )
            for a in range(DATA_COUNT)
        ]
        assert all(
            sum(
                normal_rows[a][j] * residual[a]
                for a in range(DATA_COUNT)
            ) == 0
            for j in range(DATA_COUNT - HEAD_COUNT)
        )
        solution = solve_linear(reciprocal, residual, HEAD_COUNT)
        for h in range(HEAD_COUNT):
            data_numerator[h][b] = solution[h]

    epsilon = F(1, 1_000_000)
    denominators = []
    numerators = []
    for h in range(HEAD_COUNT):
        denominators.append(
            [F(h + 1), F(1), F(2), F(4)]
            + [
                epsilon * data_denominator[h][b]
                for b in range(DATA_COUNT)
            ]
        )
        numerators.append(
            [u[h][j] / epsilon for j in range(ADDRESS_BITS + 1)]
            + [data_numerator[h][b] for b in range(DATA_COUNT)]
        )
    numerators[0] = [
        left - F(1, 2) * right
        for left, right in zip(numerators[0], denominators[0])
    ]
    return denominators, numerators


def main():
    denominators, numerators = construct_certificate()
    minimum_margin = None
    for x in product([0, 1], repeat=VARIABLE_COUNT):
        address = x[0] + 2 * x[1] + 4 * x[2]
        label = 1 if x[ADDRESS_BITS + address] else -1
        score = F(0)
        for denominator, numerator in zip(denominators, numerators):
            denominator_value = denominator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(denominator[1:], x)
            )
            numerator_value = numerator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(numerator[1:], x)
            )
            assert denominator_value > 0
            assert all(coefficient > 0 for coefficient in denominator[1:])
            score += numerator_value / denominator_value
        signed_margin = label * score
        minimum_margin = (
