#!/usr/bin/env python3
"""Exact seven-head certificate for the three-bit address function."""

from fractions import Fraction as F
from itertools import product


ADDRESS_BITS = 3
DATA_COUNT = 1 << ADDRESS_BITS
HEAD_COUNT = DATA_COUNT - 1
VARIABLE_COUNT = ADDRESS_BITS + DATA_COUNT
ADDRESSES = list(product([0, 1], repeat=ADDRESS_BITS))
NODES = [
    sum((1 << i) * bit for i, bit in enumerate(address))
    for address in ADDRESSES
]
ROW_FOR_NODE = {node: row for row, node in enumerate(NODES)}


def solve_linear(rows, right_hand_side, column_count):
    """Return one exact solution, setting all free variables to zero."""
    matrix = [
        [F(value) for value in row] + [F(right)]
        for row, right in zip(rows, right_hand_side)
    ]
    rank = 0
    pivots = []
    for column in range(column_count):
        pivot = next(
            (i for i in range(rank, len(matrix)) if matrix[i][column]),
            None,
        )
        if pivot is None:
            continue
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]
        scale = matrix[rank][column]
        matrix[rank] = [value / scale for value in matrix[rank]]
        for i in range(len(matrix)):
            if i != rank and matrix[i][column]:
                scale = matrix[i][column]
                matrix[i] = [
                    left - scale * right
                    for left, right in zip(matrix[i], matrix[rank])
                ]
        pivots.append(column)
        rank += 1
    assert all(any(row[:-1]) or not row[-1] for row in matrix)
    answer = [F(0)] * column_count
    for row, pivot in zip(matrix[:rank], pivots):
        answer[pivot] = row[-1]
    return answer


def construct_certificate():
    # Address-only Cauchy denominators A_h(a)=z(a)+h+1.
    reciprocal = [
        [F(1, node + h + 1) for h in range(HEAD_COUNT)]
        for node in NODES
    ]

    # A left-null vector of the rectangular Cauchy matrix.
    normal = []
    for a, node in enumerate(NODES):
        q_value = 1
        for h in range(HEAD_COUNT):
            q_value *= node + h + 1
        vandermonde_derivative = 1
        for b, other in enumerate(NODES):
            if b != a:
                vandermonde_derivative *= node - other
        normal.append(F(q_value, vandermonde_derivative))
    scale = max(abs(value) for value in normal)
    normal = [value / scale for value in normal]
    assert all(
        sum(normal[a] * reciprocal[a][h] for a in range(DATA_COUNT)) == 0
        for h in range(HEAD_COUNT)
    )

    # Build a Cauchy combination B supported only at z=0 and z=4.  Both
    # support points have a_1=0, so U_h(a)=beta_h*a_1 cancels identically.
    support_zero = ROW_FOR_NODE[0]
    support_half = ROW_FOR_NODE[DATA_COUNT // 2]
    supported = [F(0)] * DATA_COUNT
    supported[support_zero] = normal[support_half]
    supported[support_half] = -normal[support_zero]
    assert sum(
        normal[a] * supported[a] for a in range(DATA_COUNT)
    ) == 0
    beta = solve_linear(reciprocal, supported, HEAD_COUNT)
    assert all(
        sum(reciprocal[a][h] * beta[h] for h in range(HEAD_COUNT))
        == supported[a]
        for a in range(DATA_COUNT)
    )
    assert [1 if value > 0 else -1 for value in beta] == [
        (-1) ** (h + 1) for h in range(HEAD_COUNT)
    ]

    u_values = [
        [beta[h] * address[0] for h in range(HEAD_COUNT)]
        for address in ADDRESSES
    ]
    assert all(
        sum(
            u_values[a][h] * reciprocal[a][h]
            for h in range(HEAD_COUNT)
        ) == 0
        for a in range(DATA_COUNT)
    )

    first_order = [
        [
            -u_values[a][h] * reciprocal[a][h] ** 2
            for h in range(HEAD_COUNT)
        ]
        for a in range(DATA_COUNT)
    ]
    gamma = [
        sum(normal[a] * first_order[a][h] for a in range(DATA_COUNT))
        for h in range(HEAD_COUNT)
    ]
    assert min(gamma) < 0 < max(gamma)
    positive_index = next(h for h in range(HEAD_COUNT) if gamma[h] > 0)
    negative_index = next(h for h in range(HEAD_COUNT) if gamma[h] < 0)

    # Choose every data coefficient of every denominator strictly positive.
    # The two opposite quotient signs let positive coefficients match any
    # required Cauchy normal coordinate.
    data_denominator = [
        [F(1) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    base_dot = sum(gamma)
    for b in range(DATA_COUNT):
        target_normal = normal[ROW_FOR_NODE[b]]
        residual = target_normal - base_dot
        if residual >= 0:
            data_denominator[positive_index][b] += (
                residual / gamma[positive_index]
            )
        else:
            data_denominator[negative_index][b] += (
                residual / gamma[negative_index]
            )
        assert all(
            data_denominator[h][b] > 0 for h in range(HEAD_COUNT)
        )
        assert sum(
            gamma[h] * data_denominator[h][b]
            for h in range(HEAD_COUNT)
        ) == target_normal

    # The residual of each selector column is normal-orthogonal and hence has
    # a unique expansion in the seven Cauchy columns.
    data_numerator = [
        [F(0) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    for b in range(DATA_COUNT):
        residual = [
            F(int(NODES[a] == b))
            - sum(
                first_order[a][h] * data_denominator[h][b]
                for h in range(HEAD_COUNT)
            )
            for a in range(DATA_COUNT)
        ]
        assert sum(
            normal[a] * residual[a] for a in range(DATA_COUNT)
        ) == 0
        solution = solve_linear(reciprocal, residual, HEAD_COUNT)
        for h in range(HEAD_COUNT):
            data_numerator[h][b] = solution[h]
        assert all(
            sum(
                reciprocal[a][h] * solution[h]
                for h in range(HEAD_COUNT)
            ) == residual[a]
            for a in range(DATA_COUNT)
        )

    epsilon = F(1, 1_000_000)
    denominators = []
    numerators = []
    for h in range(HEAD_COUNT):
        denominators.append(
            [F(h + 1)]
            + [F(1 << i) for i in range(ADDRESS_BITS)]
            + [epsilon * data_denominator[h][b] for b in range(DATA_COUNT)]
        )
        numerators.append(
            [F(0), beta[h] / epsilon, F(0), F(0)]
            + [data_numerator[h][b] for b in range(DATA_COUNT)]
        )

    # The desired limiting score is y_a; subtract 1/2 exactly.
    numerators[0] = [
        left - F(1, 2) * right
        for left, right in zip(numerators[0], denominators[0])
    ]
    return denominators, numerators


def main():
    denominators, numerators = construct_certificate()
    minimum_margin = None
    for x in product([0, 1], repeat=VARIABLE_COUNT):
        address = sum((1 << i) * x[i] for i in range(ADDRESS_BITS))
        label = 1 if x[ADDRESS_BITS + address] else -1
        score = F(0)
        for denominator, numerator in zip(denominators, numerators):
            denominator_value = denominator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(denominator[1:], x)
            )
            numerator_value = numerator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(numerator[1:], x)
            )
            assert denominator_value > 0
            assert all(coefficient > 0 for coefficient in denominator[1:])
            score += numerator_value / denominator_value
        signed_margin = label * score
        minimum_margin = (
            signed_margin
            if minimum_margin is None
            else min(minimum_margin, signed_margin)
        )
    assert minimum_margin > F(454, 1000)
    print("IDX_3 seven-head rational certificate: exact")
    print(f"minimum signed margin: {minimum_margin}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Exact five-head certificate for the three-bit address function."""

from fractions import Fraction as F
from itertools import product


ADDRESS_BITS = 3
DATA_COUNT = 1 << ADDRESS_BITS
HEAD_COUNT = 5
VARIABLE_COUNT = ADDRESS_BITS + DATA_COUNT
ADDRESSES = list(product([0, 1], repeat=ADDRESS_BITS))
NODES = [
    sum((1 << i) * bit for i, bit in enumerate(address))
    for address in ADDRESSES
]
ROW_FOR_NODE = {node: row for row, node in enumerate(NODES)}


def rref(rows, column_count):
    matrix = [[F(value) for value in row] for row in rows]
    rank = 0
    pivots = []
    for column in range(column_count):
        pivot = next(
            (i for i in range(rank, len(matrix)) if matrix[i][column]),
            None,
        )
        if pivot is None:
            continue
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]
        scale = matrix[rank][column]
        matrix[rank] = [value / scale for value in matrix[rank]]
        for i in range(len(matrix)):
            if i != rank and matrix[i][column]:
                scale = matrix[i][column]
                matrix[i] = [
                    left - scale * right
                    for left, right in zip(matrix[i], matrix[rank])
                ]
        pivots.append(column)
        rank += 1
    return matrix, pivots


def nullspace(rows, column_count):
    matrix, pivots = rref(rows, column_count)
    basis = []
    for free in (j for j in range(column_count) if j not in pivots):
        vector = [F(0)] * column_count
        vector[free] = F(1)
        for row, pivot in zip(matrix[: len(pivots)], pivots):
            vector[pivot] = -row[free]
        basis.append(vector)
    return basis


def solve_linear(rows, right_hand_side, column_count):
    augmented = [
        list(row) + [right]
        for row, right in zip(rows, right_hand_side)
    ]
    matrix, pivots = rref(augmented, column_count)
    assert all(
        any(row[:column_count]) or not row[-1]
        for row in matrix
    )
    answer = [F(0)] * column_count
    for row, pivot in zip(matrix[: len(pivots)], pivots):
        answer[pivot] = row[-1]
    return answer


def positive_null_vector(rows):
    basis = nullspace(rows, HEAD_COUNT)
    assert len(basis) == 2
    first, second = basis
    candidates = [
        (first, second),
        ([-value for value in first], second),
        (second, first),
        ([-value for value in second], first),
    ]
    for base, direction in candidates:
        lower = None
        upper = None
        feasible = True
        for left, slope in zip(base, direction):
            if slope > 0:
                bound = -left / slope
                lower = bound if lower is None else max(lower, bound)
            elif slope < 0:
                bound = -left / slope
                upper = bound if upper is None else min(upper, bound)
            elif left <= 0:
                feasible = False
        if not feasible or (
            lower is not None and upper is not None and lower >= upper
        ):
            continue
        if lower is None:
            parameter = upper - 1
        elif upper is None:
            parameter = lower + 1
        else:
            parameter = (lower + upper) / 2
        result = [
            left + parameter * slope
            for left, slope in zip(base, direction)
        ]
        if all(value > 0 for value in result):
            return result
    raise AssertionError("quotient columns do not positively span")


def construct_certificate():
    reciprocal = [
        [F(1, node + h + 1) for h in range(HEAD_COUNT)]
        for node in NODES
    ]
    normal_columns = nullspace(
        list(zip(*reciprocal)),
        DATA_COUNT,
    )
    assert len(normal_columns) == DATA_COUNT - HEAD_COUNT
    normal_rows = [
        [
            normal_columns[j][a]
            for j in range(DATA_COUNT - HEAD_COUNT)
        ]
        for a in range(DATA_COUNT)
    ]

    cancellation_rows = []
    for a, address in enumerate(ADDRESSES):
        row = []
        for h in range(HEAD_COUNT):
            row.extend(
                [reciprocal[a][h]]
                + [bit * reciprocal[a][h] for bit in address]
            )
        cancellation_rows.append(row)
    cancellation_basis = nullspace(
        cancellation_rows,
        HEAD_COUNT * (ADDRESS_BITS + 1),
    )
    assert len(cancellation_basis) == 12

    # A fixed rational cancellation relation; the coefficients merely select
    # one vector in the exact nullspace above.
    combination = [4, -4, -1, 3, 1, -3, 3, 1, -3, 3, 2, -3]
    u_flat = [
        sum(
            coefficient * basis[j]
            for coefficient, basis in zip(combination, cancellation_basis)
        )
        for j in range(HEAD_COUNT * (ADDRESS_BITS + 1))
    ]
    u = [
        u_flat[h * (ADDRESS_BITS + 1):(h + 1) * (ADDRESS_BITS + 1)]
        for h in range(HEAD_COUNT)
    ]
    u_values = [
        [
            u[h][0]
            + sum(
                u[h][i + 1] * address[i]
                for i in range(ADDRESS_BITS)
            )
            for h in range(HEAD_COUNT)
        ]
        for address in ADDRESSES
    ]
    assert all(
        sum(
            u_values[a][h] * reciprocal[a][h]
            for h in range(HEAD_COUNT)
        ) == 0
        for a in range(DATA_COUNT)
    )

    first_order = [
        [
            -u_values[a][h] * reciprocal[a][h] ** 2
            for h in range(HEAD_COUNT)
        ]
        for a in range(DATA_COUNT)
    ]
    quotient = [
        [
            sum(
                normal_rows[a][j] * first_order[a][h]
                for a in range(DATA_COUNT)
            )
            for h in range(HEAD_COUNT)
        ]
        for j in range(DATA_COUNT - HEAD_COUNT)
    ]
    positive_kernel = positive_null_vector(quotient)

    data_denominator = [
        [F(0) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    data_numerator = [
        [F(0) for _ in range(DATA_COUNT)]
        for _ in range(HEAD_COUNT)
    ]
    for b in range(DATA_COUNT):
        target = normal_rows[ROW_FOR_NODE[b]]
        particular = solve_linear(quotient, target, HEAD_COUNT)
        multiplier = F(0)
        for value, direction in zip(particular, positive_kernel):
            if value <= 0:
                multiplier = max(
                    multiplier,
                    -value / direction + 1,
                )
        data_coefficients = [
            value + multiplier * direction
            for value, direction in zip(particular, positive_kernel)
        ]
        assert all(value > 0 for value in data_coefficients)
        for h in range(HEAD_COUNT):
            data_denominator[h][b] = data_coefficients[h]

        residual = [
            F(int(NODES[a] == b))
            - sum(
                first_order[a][h] * data_denominator[h][b]
                for h in range(HEAD_COUNT)
            )
            for a in range(DATA_COUNT)
        ]
        assert all(
            sum(
                normal_rows[a][j] * residual[a]
                for a in range(DATA_COUNT)
            ) == 0
            for j in range(DATA_COUNT - HEAD_COUNT)
        )
        solution = solve_linear(reciprocal, residual, HEAD_COUNT)
        for h in range(HEAD_COUNT):
            data_numerator[h][b] = solution[h]

    epsilon = F(1, 1_000_000)
    denominators = []
    numerators = []
    for h in range(HEAD_COUNT):
        denominators.append(
            [F(h + 1), F(1), F(2), F(4)]
            + [
                epsilon * data_denominator[h][b]
                for b in range(DATA_COUNT)
            ]
        )
        numerators.append(
            [u[h][j] / epsilon for j in range(ADDRESS_BITS + 1)]
            + [data_numerator[h][b] for b in range(DATA_COUNT)]
        )
    numerators[0] = [
        left - F(1, 2) * right
        for left, right in zip(numerators[0], denominators[0])
    ]
    return denominators, numerators


def main():
    denominators, numerators = construct_certificate()
    minimum_margin = None
    for x in product([0, 1], repeat=VARIABLE_COUNT):
        address = x[0] + 2 * x[1] + 4 * x[2]
        label = 1 if x[ADDRESS_BITS + address] else -1
        score = F(0)
        for denominator, numerator in zip(denominators, numerators):
            denominator_value = denominator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(denominator[1:], x)
            )
            numerator_value = numerator[0] + sum(
                coefficient * bit
                for coefficient, bit in zip(numerator[1:], x)
            )
            assert denominator_value > 0
            assert all(coefficient > 0 for coefficient in denominator[1:])
            score += numerator_value / denominator_value
        signed_margin = label * score
        minimum_margin = (
            signed_margin
            if minimum_margin is None
            else min(minimum_margin, signed_margin)
        )
    assert minimum_margin > F(109, 1000)
    print("IDX_3 five-head rational certificate: exact")
    print(f"minimum signed margin: {minimum_margin}")


if __name__ == "__main__":
    main()

