#!/usr/bin/env python3
"""Ask Z3 for a symmetry-normalized 14-by-11 cover of F_2^7."""

from subprocess import PIPE, Popen


def exactly(names, total):
    terms = " ".join(f"(ite {name} 1 0)" for name in names)
    return f"(assert (= (+ {terms}) {total}))"


def main():
    a_names = [f"a{i}" for i in range(128)]
    t_names = [f"t{i}" for i in range(128)]
    lines = ["(set-logic QF_LIA)", "(set-option :timeout 3300000)"]
    lines.extend(f"(declare-const {name} Bool)" for name in a_names + t_names)
    lines.append(exactly(a_names, 14))
    lines.append(exactly(t_names, 11))

    # Translation and GL(7,2) symmetry break for affinely spanning A.
    for value in (0, 1, 2, 4, 8, 16, 32, 64):
        lines.append(f"(assert a{value})")
    lines.append("(assert t0)")

    for target in range(128):
        witnesses = " ".join(
            f"(and a{a_value} t{target ^ a_value})"
            for a_value in range(128)
        )
        lines.append(f"(assert (or {witnesses}))")
    lines.extend(
        [
            "(check-sat)",
            "(get-value (" + " ".join(a_names + t_names) + "))",
        ]
    )
    process = Popen(["z3", "-in"], stdin=PIPE, stdout=PIPE, stderr=PIPE, text=True)
    stdout, stderr = process.communicate("\n".join(lines))
    print(stdout, end="", flush=True)
    if stderr:
        print(stderr, end="", flush=True)


if __name__ == "__main__":
    main()

