"""Ask Z3 for an affine-basis-normalized 11-by-7 cover of F_2^6."""

from subprocess import PIPE, Popen


def exactly(names, total):
    arguments = " ".join(names)
    return [
        f"(assert ((_ at-most {total}) {arguments}))",
        f"(assert ((_ at-least {total}) {arguments}))",
    ]


def main():
    group = 64
    a_names = [f"a{i}" for i in range(group)]
    t_names = [f"t{i}" for i in range(group)]
    lines = ["(set-logic QF_FD)", "(set-option :timeout 3300000)"]
    lines.extend(f"(declare-const {name} Bool)" for name in a_names + t_names)
    lines.extend(exactly(a_names, 11))
    lines.extend(exactly(t_names, 7))
    for value in (0, 1, 2, 4, 8, 16, 32):
        lines.append(f"(assert a{value})")
    lines.append("(assert t0)")
    for target in range(group):
        witnesses = " ".join(
            f"(and a{a_value} t{target ^ a_value})"
            for a_value in range(group)
        )
        lines.append(f"(assert (or {witnesses}))")
    lines.extend(
        [
            "(check-sat)",
            "(get-value (" + " ".join(a_names + t_names) + "))",
        ]
    )
    process = Popen(["z3", "-in"], stdin=PIPE, stdout=PIPE, stderr=PIPE, text=True)
    stdout, stderr = process.communicate("\n".join(lines))
    print(stdout, end="", flush=True)
    if stderr:
        print(stderr, end="", flush=True)


if __name__ == "__main__":
    main()

