import itertools
from fractions import Fraction
from functools import lru_cache

def rank(M):
 A=[[Fraction(z) for z in row] for row in M]; r=0
 for c in range(len(A[0]) if A else 0):
  p=next((i for i in range(r,len(A)) if A[i][c]),None)
  if p is None: continue
  A[r],A[p]=A[p],A[r]; q=A[r][c]; A[r]=[z/q for z in A[r]]
  for i in range(r+1,len(A)):
   if A[i][c]:
    q=A[i][c]; A[i]=[a-q*b for a,b in zip(A[i],A[r])]
  r+=1
 return r

def hyper_normal(B,n):
 A=[[Fraction(1)]+[Fraction(v) for v in x] for x in B]
 # null vector if rank n
 M=[row[:] for row in A]; rr=0;pivs=[]
 for c in range(n+1):
  p=next((i for i in range(rr,len(M)) if M[i][c]),None)
  if p is None:continue
  M[rr],M[p]=M[p],M[rr];q=M[rr][c];M[rr]=[z/q for z in M[rr]]
  for i in range(len(M)):
   if i!=rr and M[i][c]:
    q=M[i][c];M[i]=[a-q*b for a,b in zip(M[i],M[rr])]
  pivs.append(c);rr+=1
 if rr!=n:return None
 free=next(c for c in range(n+1) if c not in pivs); z=[Fraction(0)]*(n+1);z[free]=1
 for i,c in reversed(list(enumerate(pivs))):z[c]=-sum(M[i][j]*z[j] for j in range(c+1,n+1))
 return z

for n in range(2,7):
 X=list(itertools.product([0,1],repeat=n)); V=X[1:]; N=len(V); full=N//n; rem=N%n
 ordinary=[]
 for comb in itertools.combinations(range(N),n):
  B=[V[i] for i in comb]
  z=hyper_normal(B,n)
  if z is None:continue
  zeros=[i for i,x in enumerate(V) if sum(a*b for a,b in zip(z,[1]+list(x)))==0]
  if len(zeros)==n:ordinary.append((sum(1<<i for i in comb),comb))
 print('n',n,'vertices',N,'ordinary bases',len(ordinary),'need full blocks',full,'rem',rem,flush=True)
 if n>5: continue
 byv=[[] for _ in range(N)]
 for mask,comb in ordinary:
  for i in comb:byv[i].append(mask)
 target_full=full
 @lru_cache(None)
 def dfs(mask,k):
  if k==0:return ()
  # leave exactly rem vertices uncovered at end; select constrained covered vertex
  uncovered=[i for i in range(N) if not(mask>>i)&1]
  if len(uncovered)<k*n:return None
  # choose vertex with fewest compatible blocks, but it may be a residual vertex.
  cand_counts=[]
  for i in uncovered:
   opts=[b for b in byv[i] if not b&mask]
   cand_counts.append((len(opts),i,opts))
  for _,i,opts in sorted(cand_counts):
   for b in opts:
    out=dfs(mask|b,k-1)
    if out is not None:return (b,)+out
   # allow i to be residual only if residual capacity exists; naive branch handled by trying next vertex
  return None
 sol=dfs(0,target_full)
 if sol is None:
  # brute allow arbitrary residual by iterate residual subsets when small
  found=None
  for residual in itertools.combinations(range(N),rem):
   rmask=sum(1<<i for i in residual)
   @lru_cache(None)
   def exact(mask,k):
    if k==0:return () if (mask|rmask)==(1<<N)-1 else None
    i=next(i for i in range(N) if not ((mask|rmask)>>i)&1)
    for b in byv[i]:
     if not b&(mask|rmask):
      out=exact(mask|b,k-1)
      if out is not None:return (b,)+out
    return None
   out=exact(0,target_full)
   if out is not None:found=(residual,out);break
  sol=found
 print(' partition found',sol is not None,flush=True)
